import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { AuthProvider } from './context/AuthContext';

// Component imports
import Header from './components/common/Header';
import Footer from './components/common/Footer';
import Home from './components/public/Home';
import VendorList from './components/public/VendorList';
import VendorDetails from './components/public/VendorDetails';
import Login from './components/auth/Login';
import Register from './components/auth/Register';
import EmailVerification from './components/auth/EmailVerification'; // Add this import
import ProtectedRoute from './components/auth/ProtectedRoute';
import VendorDashboard from './components/vendor/VendorDashboard';
import VendorProfile from './components/vendor/VendorProfile';
import ApplicationForm from './components/vendor/ApplicationForm';
import ApplicationStatus from './components/vendor/ApplicationStatus';
import AdminDashboard from './components/admin/AdminDashboard';
import VendorManagement from './components/admin/VendorManagement';
import ApplicationManagement from './components/admin/ApplicationManagement';
import ApplicationDetails from './components/admin/ApplicationDetails';

import './App.css';

function App() {
  return (
    <AuthProvider>
      <Router>
        <div className="App">
          <Header />
          <main className="main-content">
            <Routes>
              {/* Public routes */}
              <Route path="/" element={<Home />} />
              <Route path="/vendors" element={<VendorList />} />
              <Route path="/vendor/:id" element={<VendorDetails />} />
              <Route path="/login" element={<Login />} />
              <Route path="/register" element={<Register />} />
              <Route path="/verify-email" element={<EmailVerification />} /> {/* Add this route */}
              
              {/* Vendor protected routes */}
              <Route path="/vendor-dashboard" element={
                <ProtectedRoute roles={['ROLE_VENDOR']}>
                  <VendorDashboard />
                </ProtectedRoute>
              } />
              <Route path="/vendor-profile" element={
                <ProtectedRoute roles={['ROLE_VENDOR']}>
                  <VendorProfile />
                </ProtectedRoute>
              } />
              <Route path="/application" element={
                <ProtectedRoute roles={['ROLE_VENDOR']}>
                  <ApplicationForm />
                </ProtectedRoute>
              } />
              <Route path="/application-status" element={
                <ProtectedRoute roles={['ROLE_VENDOR']}>
                  <ApplicationStatus />
                </ProtectedRoute>
              } />
              
              {/* Admin protected routes */}
              <Route path="/admin-dashboard" element={
                <ProtectedRoute roles={['ROLE_ADMIN']}>
                  <AdminDashboard />
                </ProtectedRoute>
              } />
              <Route path="/admin/vendors" element={
                <ProtectedRoute roles={['ROLE_ADMIN']}>
                  <VendorManagement />
                </ProtectedRoute>
              } />
              <Route path="/admin/applications" element={
                <ProtectedRoute roles={['ROLE_ADMIN']}>
                  <ApplicationManagement />
                </ProtectedRoute>
              } />
              <Route path="/admin/application/:id" element={
                <ProtectedRoute roles={['ROLE_ADMIN']}>
                  <ApplicationDetails />
                </ProtectedRoute>
              } />
            </Routes>
          </main>
          <Footer />
        </div>
      </Router>
    </AuthProvider>
  );
}

export default App;
